// Captura os dados do evento do Frigate
const payload = msg.payload;

// Altere para a lista de pessoas autorizadas e o limite mínimo de confiança (ex: 0.70 = 70%)
const pessoasAutorizadas = ["gabriel pimentel", "maria"];
const minConfidence = 0.10;

// Verifica se a estrutura do evento é válida e se o objeto é uma pessoa
if (payload.after && payload.after.label === "person") {
    const subLabel = payload.after.sub_label[0] || "---"; // Nome da pessoa reconhecida
    const score = payload.after.score;       // Grau de confiabilidade (0.0 a 1.0)
    const type = payload.type;               // Tipo do evento: "new", "update" ou "end"

    // Filtra apenas eventos novos ou atualizados onde a pessoa é reconhecida com confiança suficiente
    if (type !== "end" && subLabel && pessoasAutorizadas.includes(subLabel.toLowerCase())) {
        node.warn("3. Evento novo");
        node.warn("4. " + score + ">=" + minConfidence);
        if (score >= minConfidence) {
            node.warn("4. "+score +">=" +minConfidence);
            // Monta o payload de comando para o ESP32 com os dados do reconhecimento
            msg.topic = "building/gate/command";
            msg.payload = "1";
            // msg.payload = {
            //     acao: "abrir",
            //     pessoa: subLabel,
            //     confiabilidade: Math.round(score * 100) + "%"
            // };

            return msg; // Envia a mensagem para o próximo nó (mqtt out)
        }
    }
}

// Retorna null caso não atenda aos critérios (nenhuma ação será disparada)
return null;
